    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "pch-itinerary-surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "title_text",
            "intro_text",
            "context_header",
            "context_text",
            "daily_guide_header",
            "daily_guide_list",
            "actions_header",
            "action_button",
            "gallery_header",
            "gallery_row",
            "sources_header",
            "sources_list"
          ]
        },
        {
          "id": "title_text",
          "component": "Text",
          "variant": "h2",
          "text": "Pacific Coast Highway Photography Itinerary: SF to LA in 4 Days"
        },
        {
          "id": "intro_text",
          "component": "Text",
          "text": "This itinerary outlines a 4-day road trip from San Francisco to Los Angeles, focusing on photography and scenic coastal views. The plan is paced to keep daily driving under 4 hours, allowing ample time for exploration, hiking, and capturing the stunning California coastline."
        },
        {
          "id": "context_header",
          "component": "Text",
          "variant": "h3",
          "text": "Trip Planning Context"
        },
        {
          "id": "context_text",
          "component": "Text",
          "text": "This plan assumes you are traveling when Highway 1 is fully open. This route, particularly through Big Sur, is subject to periodic closures due to landslides. It is critical to check road conditions immediately before and during your trip. The driving times provided are estimates for active driving and do not include time for stops, meals, or potential traffic delays."
        },
        {
          "id": "daily_guide_header",
          "component": "Text",
          "variant": "h3",
          "text": "Daily Driving and Photography Guide"
        },
        {
          "id": "daily_guide_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "day1_card",
            "day2_card",
            "day3_card",
            "day4_card"
          ]
        },
        {
          "id": "day1_card",
          "component": "Card",
          "child": "day1_col"
        },
        {
          "id": "day1_col",
          "component": "Column",
          "children": [
            "day1_title",
            "day1_driving_time",
            "day1_stop_row",
            "day1_hike_row",
            "day1_stay_row"
          ]
        },
        {
          "id": "day1_title",
          "component": "Text",
          "variant": "h4",
          "text": "Day 1: The Northern Coast | San Francisco to Carmel-by-the-Sea"
        },
        {
          "id": "day1_driving_time",
          "component": "Text",
          "variant": "caption",
          "text": "Driving Time: ~2 hours 30 minutes (125 miles)"
        },
        {
          "id": "day1_stop_row",
          "component": "Row",
          "align": "center",
          "children": [
            "camera_icon_1",
            "day1_stop_text"
          ]
        },
        {
          "id": "camera_icon_1",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000002_01_1_camera.svg"
        },
        {
          "id": "day1_stop_text",
          "component": "Text",
          "weight": 1,
          "text": "Major Scenic Stop: Pigeon Point Lighthouse. This historic 115-foot lighthouse offers a classic coastal California photo opportunity against the cliffs and ocean."
        },
        {
          "id": "day1_hike_row",
          "component": "Row",
          "align": "center",
          "children": [
            "hike_icon_1",
            "day1_hike_text"
          ]
        },
        {
          "id": "hike_icon_1",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000036_01_2_house.svg"
        },
        {
          "id": "day1_hike_text",
          "component": "Text",
          "weight": 1,
          "text": "Optional Short Hike: Point Lobos State Natural Reserve. The Sea Lion Point Trail (0.6-mile loop) provides dramatic ocean views, access to tide pools, and abundant wildlife photography chances."
        },
        {
          "id": "day1_stay_row",
          "component": "Row",
          "align": "center",
          "children": [
            "stay_icon_1",
            "day1_stay_text"
          ]
        },
        {
          "id": "stay_icon_1",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000006_01_5_calendar-event.svg"
        },
        {
          "id": "day1_stay_text",
          "component": "Text",
          "weight": 1,
          "text": "Overnight Stay: Carmel-by-the-Sea. A charming town known for its European-style village, art galleries, and beautiful beach."
        },
        {
          "id": "day2_card",
          "component": "Card",
          "child": "day2_col"
        },
        {
          "id": "day2_col",
          "component": "Column",
          "children": [
            "day2_title",
            "day2_driving_time",
            "day2_stop_row",
            "day2_hike_row",
            "day2_stay_row"
          ]
        },
        {
          "id": "day2_title",
          "component": "Text",
          "variant": "h4",
          "text": "Day 2: The Heart of Big Sur | Carmel-by-the-Sea to Cambria"
        },
        {
          "id": "day2_driving_time",
          "component": "Text",
          "variant": "caption",
          "text": "Driving Time: ~2 hours 30 minutes (90 miles)"
        },
        {
          "id": "day2_stop_row",
          "component": "Row",
          "align": "center",
          "children": [
            "camera_icon_2",
            "day2_stop_text"
          ]
        },
        {
          "id": "camera_icon_2",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000002_01_1_camera.svg"
        },
        {
          "id": "day2_stop_text",
          "component": "Text",
          "weight": 1,
          "text": "Major Scenic Stop: Bixby Creek Bridge. The most iconic landmark on Highway 1. Park in the designated pullouts on the north side of the bridge for the best and safest photographic angles."
        },
        {
          "id": "day2_hike_row",
          "component": "Row",
          "align": "center",
          "children": [
            "hike_icon_2",
            "day2_hike_text"
          ]
        },
        {
          "id": "hike_icon_2",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000036_01_2_house.svg"
        },
        {
          "id": "day2_hike_text",
          "component": "Text",
          "weight": 1,
          "text": "Optional Short Hike: Partington Cove Trail. This 1-mile round-trip hike descends through a 60-foot tunnel to a secluded, rocky cove, offering a unique perspective of the Big Sur coast."
        },
        {
          "id": "day2_stay_row",
          "component": "Row",
          "align": "center",
          "children": [
            "stay_icon_2",
            "day2_stay_text"
          ]
        },
        {
          "id": "stay_icon_2",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000006_01_5_calendar-event.svg"
        },
        {
          "id": "day2_stay_text",
          "component": "Text",
          "weight": 1,
          "text": "Overnight Stay: Cambria. A quaint coastal village with a relaxed atmosphere, perfect for resting after a day of breathtaking views."
        },
        {
          "id": "day3_card",
          "component": "Card",
          "child": "day3_col"
        },
        {
          "id": "day3_col",
          "component": "Column",
          "children": [
            "day3_title",
            "day3_driving_time",
            "day3_stop_row",
            "day3_hike_row",
            "day3_stay_row"
          ]
        },
        {
          "id": "day3_title",
          "component": "Text",
          "variant": "h4",
          "text": "Day 3: The Central Coast Transition | Cambria to Santa Barbara"
        },
        {
          "id": "day3_driving_time",
          "component": "Text",
          "variant": "caption",
          "text": "Driving Time: ~3 hours (130 miles)"
        },
        {
          "id": "day3_stop_row",
          "component": "Row",
          "align": "center",
          "children": [
            "camera_icon_3",
            "day3_stop_text"
          ]
        },
        {
          "id": "camera_icon_3",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000002_01_1_camera.svg"
        },
        {
          "id": "day3_stop_text",
          "component": "Text",
          "weight": 1,
          "text": "Major Scenic Stop: Elephant Seal Vista Point. Just north of San Simeon, this viewpoint offers incredible opportunities to photograph the massive northern elephant seals that haul out on the beach year-round."
        },
        {
          "id": "day3_hike_row",
          "component": "Row",
          "align": "center",
          "children": [
            "hike_icon_3",
            "day3_hike_text"
          ]
        },
        {
          "id": "hike_icon_3",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000036_01_2_house.svg"
        },
        {
          "id": "day3_hike_text",
          "component": "Text",
          "weight": 1,
          "text": "Optional Short Hike: Fiscalini Ranch Preserve Bluff Trail. Before leaving Cambria, walk a portion of this easy 1-mile coastal trail for stunning views of the rocky shoreline and tide pools."
        },
        {
          "id": "day3_stay_row",
          "component": "Row",
          "align": "center",
          "children": [
            "stay_icon_3",
            "day3_stay_text"
          ]
        },
        {
          "id": "stay_icon_3",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000006_01_5_calendar-event.svg"
        },
        {
          "id": "day3_stay_text",
          "component": "Text",
          "weight": 1,
          "text": "Overnight Stay: Santa Barbara. Known as \"The American Riviera,\" this city features beautiful Spanish-style architecture, a palm-lined waterfront, and a mountainous backdrop."
        },
        {
          "id": "day4_card",
          "component": "Card",
          "child": "day4_col"
        },
        {
          "id": "day4_col",
          "component": "Column",
          "children": [
            "day4_title",
            "day4_driving_time",
            "day4_stop_row",
            "day4_hike_row",
            "day4_stay_row"
          ]
        },
        {
          "id": "day4_title",
          "component": "Text",
          "variant": "h4",
          "text": "Day 4: The Southern Approach | Santa Barbara to Los Angeles"
        },
        {
          "id": "day4_driving_time",
          "component": "Text",
          "variant": "caption",
          "text": "Driving Time: ~2 hours (100 miles)"
        },
        {
          "id": "day4_stop_row",
          "component": "Row",
          "align": "center",
          "children": [
            "camera_icon_4",
            "day4_stop_text"
          ]
        },
        {
          "id": "camera_icon_4",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000002_01_1_camera.svg"
        },
        {
          "id": "day4_stop_text",
          "component": "Text",
          "weight": 1,
          "text": "Major Scenic Stop: Point Dume State Beach & Preserve. Located in Malibu, this promontory offers panoramic views of the coast, Zuma Beach, and Paradise Cove. It's a prime spot for sunset photography."
        },
        {
          "id": "day4_hike_row",
          "component": "Row",
          "align": "center",
          "children": [
            "hike_icon_4",
            "day4_hike_text"
          ]
        },
        {
          "id": "hike_icon_4",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000036_01_2_house.svg"
        },
        {
          "id": "day4_hike_text",
          "component": "Text",
          "weight": 1,
          "text": "Optional Short Hike: Point Dume Nature Preserve Trail. A short, sandy loop trail (approx. 1 mile) takes you to the top of the bluff for the best vantage points."
        },
        {
          "id": "day4_stay_row",
          "component": "Row",
          "align": "center",
          "children": [
            "stay_icon_4",
            "day4_stay_text"
          ]
        },
        {
          "id": "stay_icon_4",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000006_01_5_calendar-event.svg"
        },
        {
          "id": "day4_stay_text",
          "component": "Text",
          "weight": 1,
          "text": "Final Destination: Los Angeles. Conclude your trip by arriving in the LA area, for example, near the iconic Santa Monica Pier."
        },
        {
          "id": "actions_header",
          "component": "Text",
          "variant": "h3",
          "text": "Quick Actions"
        },
        {
          "id": "action_button",
          "component": "Button",
          "variant": "primary",
          "child": "action_button_child_row",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://roads.dot.ca.gov/"
              }
            }
          }
        },
        {
          "id": "action_button_child_row",
          "component": "Row",
          "align": "center",
          "children": [
            "compass_icon",
            "action_button_text"
          ]
        },
        {
          "id": "compass_icon",
          "component": "Image",
          "variant": "icon",
          "url": "../assets/r_000035_01_7_compass.svg"
        },
        {
          "id": "action_button_text",
          "component": "Text",
          "text": "Check CA Highway 1 Road Conditions"
        },
        {
          "id": "gallery_header",
          "component": "Text",
          "variant": "h3",
          "text": "Image Gallery"
        },
        {
          "id": "gallery_row",
          "component": "Row",
          "justify": "spaceAround",
          "children": [
            "gallery_img_1",
            "gallery_img_2",
            "gallery_img_3",
            "gallery_img_4"
          ]
        },
        {
          "id": "gallery_img_1",
          "component": "Image",
          "variant": "smallFeature",
          "url": "../assets/r_000036_01_4_bixby-bridge.jpg",
          "accessibility": {
            "label": "Bixby Bridge"
          }
        },
        {
          "id": "gallery_img_2",
          "component": "Image",
          "variant": "smallFeature",
          "url": "../assets/r_000036_01_5_mcway-falls.jpg",
          "accessibility": {
            "label": "McWay Falls"
          }
        },
        {
          "id": "gallery_img_3",
          "component": "Image",
          "variant": "smallFeature",
          "url": "../assets/r_000036_01_6_elephant-seal.jpg",
          "accessibility": {
            "label": "Elephant Seals at Piedras Blancas"
          }
        },
        {
          "id": "gallery_img_4",
          "component": "Image",
          "variant": "smallFeature",
          "url": "../assets/r_000036_01_7_malibu-coast.jpg",
          "accessibility": {
            "label": "Point Dume in Malibu"
          }
        },
        {
          "id": "sources_header",
          "component": "Text",
          "variant": "h3",
          "text": "Sources"
        },
        {
          "id": "sources_list",
          "component": "Column",
          "align": "start",
          "children": [
            "source1_button",
            "source2_button"
          ]
        },
        {
          "id": "source1_button",
          "component": "Button",
          "variant": "borderless",
          "child": "source1_text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.parks.ca.gov/"
              }
            }
          }
        },
        {
          "id": "source1_text",
          "component": "Text",
          "text": "California Department of Parks and Recreation"
        },
        {
          "id": "source2_button",
          "component": "Button",
          "variant": "borderless",
          "child": "source2_text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://dot.ca.gov/"
              }
            }
          }
        },
